const TABLE = constants.CONDITION_BUCKETS_TABLE;
const WS = constants.WS;
if (!TABLE) { console.warn('[BUCKET_MAP] CONDITION_BUCKETS_TABLE constant missing'); await actions.setVariable('BUCKET_MAP', {}); return {}; }
try {
  const r = await fetch(window.location.origin + '/api/tooljet-db/proxy/' + TABLE + '?select=variable,bucket', { credentials:'include', headers:{ 'Tj-Workspace-Id': WS } });
  const rows = await r.json();
  const map = {};
  (Array.isArray(rows) ? rows : []).forEach(row => { if (row && row.variable && row.bucket) map[row.variable] = row.bucket; });
  console.log('[BUCKET_MAP] loaded', Object.keys(map).length, 'entries');
  await actions.setVariable('BUCKET_MAP', map);
  return map;
} catch (e) {
  console.error('[BUCKET_MAP] load failed', e);
  await actions.setVariable('BUCKET_MAP', {});
  return {};
}
